set -euo pipefail; SDK="${ANDROID_SDK_ROOT:-${ANDROID_HOME:-$HOME/Library/Android/sdk}}"; ADB="$(command -v adb || true)"; if [ -z "$ADB" ] && [ -x "$SDK/platform-tools/adb" ]; then ADB="$SDK/platform-tools/adb"; fi; test -n "$ADB"; test "$($ADB devices | awk 'NR>1 && $2=="device"{n++} END{print n+0}')" -eq 1; $ADB logcat -c; $ADB shell monkey -p link.localclimate.app -c android.intent.category.LAUNCHER 1 >/dev/null; sleep 2; PID="$($ADB shell pidof link.localclimate.app | tr -d '\r')"; test -n "$PID"; SOCKET="$($ADB shell cat /proc/net/unix | tr -d '\r' | awk -v pid="$PID" '$0 ~ /webview_devtools_remote/ && $0 ~ pid {print $8}' | sed 's/^@//' | tail -1)"; if [ -z "$SOCKET" ]; then SOCKET="$($ADB shell cat /proc/net/unix | tr -d '\r' | awk '/webview_devtools_remote/{print $8}' | sed 's/^@//' | tail -1)"; fi; test -n "$SOCKET"; $ADB forward --remove tcp:9222 >/dev/null 2>&1 || true; $ADB forward tcp:9222 localabstract:$SOCKET >/dev/null; trap '$ADB forward --remove tcp:9222 >/dev/null 2>&1 || true' EXIT; node <<'NODE'
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
const targets = await (await fetch('http://127.0.0.1:9222/json/list')).json();
const page = targets.find((t) => t.type === 'page' && t.url === 'https://localhost/');
if (!page?.webSocketDebuggerUrl) throw new Error('Local Climate Link WebView target not found');
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((resolve, reject) => { ws.addEventListener('open', resolve, { once: true }); ws.addEventListener('error', reject, { once: true }); });
let nextId = 1;
const pending = new Map();
ws.addEventListener('message', (event) => { const msg = JSON.parse(String(event.data)); if (msg.id && pending.has(msg.id)) { const { resolve, reject } = pending.get(msg.id); pending.delete(msg.id); msg.error ? reject(new Error(JSON.stringify(msg.error))) : resolve(msg); } });
const evaluate = (expression) => new Promise((resolve, reject) => { const id = nextId++; pending.set(id, { resolve, reject }); ws.send(JSON.stringify({ id, method: 'Runtime.evaluate', params: { expression, returnByValue: true, awaitPromise: true } })); });
const value = async (expression) => (await evaluate(expression)).result.result.value;
const plugsText = await value('document.body.innerText');
console.log('=== PLUGS DOM ===\n' + plugsText);
if (!(plugsText.includes('No plugs added.') || plugsText.includes('Brak dodanych gniazdek.'))) throw new Error('Plugs empty label missing');
if (plugsText.includes('No automations') || plugsText.includes('Brak automatyzacji')) throw new Error('Legacy automation empty label still visible on empty Plugs dashboard');
const plugsIcon = await value(

);
if (!plugsIcon) throw new Error('Plugs empty-state icon missing');
const clicked = await value(

);
if (!clicked) throw new Error('Thermometers navigation button not found');
await sleep(500);
const thermoText = await value('document.body.innerText');
console.log('=== THERMOMETERS DOM ===\n' + thermoText);
if (!(thermoText.includes('No thermometers added.') || thermoText.includes('Brak dodanych termometrów.'))) throw new Error('Thermometers empty label missing');
const thermoIcon = await value(

);
if (!thermoIcon) throw new Error('Thermometers empty-state icon missing');
ws.close();
NODE
echo '=== FOCUS ==='; $ADB shell dumpsys window | grep -m2 -E 'mCurrentFocus|mFocusedApp' || true; echo '=== ERROR CHECK ==='; if $ADB logcat -d -v brief | grep -E 'FATAL EXCEPTION|ANR in link.localclimate.app'; then exit 31; else echo NO_FATAL_OR_ANR; fi; test -z "$(git status --porcelain --untracked-files=no)"; git rev-parse HEAD
